import {toolBillingServiceTypes} from './workspace/tool-pricing-catalog.mjs';
export {toolBillingServiceTypes};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const toolBillingModes=Object.freeze({inherit:'继承科研智能助手',free:'免费',paid:'独立按权益计费',disabled:'暂停'});
export function toolBillingRulesValid(rules){return Number.isSafeInteger(rules?.version)&&rules.version>0&&Array.isArray(rules.services)&&rules.services.length===toolBillingServiceTypes.length&&toolBillingServiceTypes.every(({key})=>rules.services.filter(s=>s?.key===key).length===1&&rules.services.some(s=>s.key===key&&Object.hasOwn(toolBillingModes,s.mode)&&(s.mode==='paid'?Number.isSafeInteger(s.creditCost)&&s.creditCost>=1&&s.creditCost<=100000:s.creditCost===null)));}
export function toolBillingPayload(form,version){
 if(!Number.isSafeInteger(version)||version<1)throw Error('科研工具计价信息未取得，请刷新后重试。');
 const services=toolBillingServiceTypes.map(({key})=>{const mode=form.elements[key+'Mode']?.value,cost=form.elements[key+'Cost']?.value.trim()||'';return{key,mode,creditCost:mode==='paid'&&/^[1-9]\d{0,5}$/.test(cost)?Number(cost):null};});
 if(!toolBillingRulesValid({version,services}))throw Error('独立计费每次积分需为 1–100000 的整数；继承、免费或暂停无需填写积分。');return {version,services};
}
export function toolBillingPage(rules){
 const valid=toolBillingRulesValid(rules),groups=[...new Set(toolBillingServiceTypes.map(s=>s.group))];
 return `<section class="panel tool-billing-panel" aria-labelledby="tool-billing-title"><div class="panel-heading"><div><h2 id="tool-billing-title">科研工具计费</h2><p>每个具体功能可单独定价、免费开放或暂停；未单独设置时继承科研智能助手。</p></div><span class="badge blue">${toolBillingServiceTypes.length} 项独立服务</span></div><form id="tool-billing-form" data-tool-billing-form><p class="billing-flow">默认继承现有价格；只有选择“继承”的项目随科研智能助手定价变化，独立设置的项目需单独调整或暂停。会员及套餐优先于积分；支持具体功能专属次数，也可使用科研智能助手通用额度。修改不会重算历史订单、已预占任务或已结算记录。</p>${valid?groups.map(group=>`<section class="tool-billing-group"><h3>${esc(group)}</h3><div class="tool-billing-rows">${toolBillingServiceTypes.filter(s=>s.group===group).map(({key,title})=>{const item=rules.services.find(s=>s.key===key);return `<article class="tool-billing-row" data-tool-billing-service="${key}"><div><strong>${title}</strong><small>${item.available?'服务已接通':'服务未接通'}</small></div><label for="tool-billing-${key}-mode">计价方式<select id="tool-billing-${key}-mode" name="${key}Mode" data-tool-billing-mode="${key}">${Object.entries(toolBillingModes).map(([mode,label])=>`<option value="${mode}" ${item.mode===mode?'selected':''}>${label}</option>`).join('')}</select></label><label for="tool-billing-${key}-cost">积分 / 次<input id="tool-billing-${key}-cost" name="${key}Cost" type="text" inputmode="numeric" maxlength="6" placeholder="1–100000" value="${item.mode==='paid'?item.creditCost:''}" ${item.mode==='paid'?'':'disabled'}></label><span data-tool-effective="${key}" class="tool-billing-effective">${item.effectiveMode==='paid'?`${esc(item.effectiveCreditCost)} 积分 / 次`:item.effectiveMode==='free'?'当前免费':'当前暂停'}</span></article>`;}).join('')}</div></section>`).join(''):'<p class="billing-unavailable" role="status">科研工具计价信息暂未取得，请刷新后重试。</p>'}<div class="billing-save-bar"><p>本地文档解析、手动编辑与导出不因设置 AI 价格而收费。</p><button class="button primary" type="submit" ${valid?'':'disabled'}>保存科研工具计费</button></div><p class="form-error" role="alert" hidden></p><span class="settings-note payment-dirty" hidden>有科研工具计价修改尚未保存</span></form></section>`;
}
